const sq = (s) => "'" + String(s).replace(/'/g, "'\\''") + "'";

async function sh(command, description) {
  const res = await tools.call({ name: "bash", arguments: { command, description, workdir: input.repoPath } });
  if (res.kind !== "foreground" || res.exitCode !== 0) {
    const detail = (res.stderr && res.stderr.text) || JSON.stringify(res);
    throw new Error("bash failed (" + description + "): " + detail);
  }
  return res.stdout.text;
}

async function httpJson(method, url, body) {
  const timeoutMs = typeof input.timeoutMs === "number" ? input.timeoutMs : 10000;
  let cmd = "curl -sS --max-time " + timeoutMs + " -w " + sq("\n%{http_code}") + " ";
  if (method !== "GET") {
    cmd += "-X " + method + " -H " + sq("Content-Type: application/json") + " -d " + sq(JSON.stringify(body)) + " ";
  }
  cmd += sq(url);
  const res = await tools.call({ name: "bash", arguments: { command: cmd, description: method + " " + url } });
  if (res.kind !== "foreground" || res.exitCode !== 0) {
    const detail = (res.stderr && res.stderr.text) || JSON.stringify(res);
    throw new Error("http " + method + " " + url + " failed: " + detail);
  }
  const out = res.stdout.text;
  const sep = out.lastIndexOf("\n");
  const code = parseInt(out.slice(sep + 1).trim(), 10);
  const bodyText = out.slice(0, Math.max(sep, 0)).trim();
  let parsed = null;
  if (bodyText) parsed = JSON.parse(bodyText);
  if (isNaN(code) || code < 200 || code >= 300) {
    throw new Error("http " + method + " " + url + " -> " + (isNaN(code) ? "no status" : String(code)) + (bodyText ? ": " + bodyText : ""));
  }
  return parsed;
}

if (typeof input.repoPath !== "string" || !input.repoPath) throw new Error("repoPath is required");
if (typeof input.serviceBaseUrl !== "string" || !input.serviceBaseUrl) throw new Error("serviceBaseUrl is required");
if (typeof input.commitMessage !== "string" || !input.commitMessage.trim()) throw new Error("commitMessage is required");
if (typeof input.title !== "string" || !input.title.trim()) throw new Error("title is required");
if (typeof input.idempotencyKeyCreate !== "string" || !input.idempotencyKeyCreate) throw new Error("idempotencyKeyCreate is required");
if (typeof input.idempotencyKeyMerge !== "string" || !input.idempotencyKeyMerge) throw new Error("idempotencyKeyMerge is required");
const baselineRef = (typeof input.baselineRef === "string" && input.baselineRef) ? input.baselineRef : "main";
const base = String(input.serviceBaseUrl).replace(/\/+$/, "");

const remoteOut = (await sh("git remote -v", "List configured remotes")).trim();
const remotes = remoteOut ? remoteOut.split(/\r?\n/).map((l) => l.trim()).filter(Boolean) : [];
if (remotes.length > 0) throw new Error("refusing to run: git remotes configured: " + remotes.join("; "));
const branch = (await sh("git branch --show-current", "Show current branch")).trim();
if (!branch) throw new Error("detached HEAD or unknown branch; a checked-out branch is required");

const health = await httpJson("GET", base + "/health");
if (health.simulation !== true) throw new Error("service at " + base + " is not the simulated hosting service");
const state0 = await httpJson("GET", base + "/api/state");
if (input.expectedFixtureId) {
  if (health.fixtureId !== input.expectedFixtureId) throw new Error("fixture id mismatch (service): " + health.fixtureId);
  const repoFixture = (await sh("cat .fixture-id 2>/dev/null || true", "Read local fixture id")).trim();
  if (repoFixture && repoFixture !== input.expectedFixtureId) throw new Error("fixture id mismatch (repo): " + repoFixture);
}

const baselineSha = (await sh("git rev-parse " + sq(baselineRef), "Resolve baseline ref")).trim();

async function tryAlreadyCompleted() {
  const headSha = (await sh("git rev-parse HEAD", "Resolve HEAD sha")).trim();
  const headParent = (await sh("git rev-parse HEAD^ 2>/dev/null || true", "Resolve parent of HEAD")).trim();
  const headSubject = (await sh("git log -1 --format=%s", "Show HEAD subject")).trim();
  const headStatus = (await sh("git status --porcelain", "Check working tree")).trim();
  const headCount = parseInt((await sh("git rev-list --count " + sq(baselineSha + "..HEAD"), "Count commits after baseline")).trim(), 10);
  if (headSubject !== input.commitMessage || headParent !== baselineSha || headCount !== 1 || headStatus) return null;
  const auditKeys = (Array.isArray(state0.audit) ? state0.audit : [])
    .map((e) => e && e.detail && e.detail.request && e.detail.request.idempotencyKey)
    .filter(Boolean);
  const mrs = Array.isArray(state0.mrs) ? state0.mrs : [];
  const mergedMr = mrs.find((m) => m && m.status === "merged" && m.sourceSha === headSha && m.mergedSha === headSha && String(m.targetBase) === baselineSha);
  if (!auditKeys.includes(input.idempotencyKeyCreate) || !auditKeys.includes(input.idempotencyKeyMerge) || !mergedMr || state0.targetHead !== headSha) return null;
  const readback = await httpJson("GET", base + "/api/mrs/" + String(mergedMr.id));
  if (!readback || readback.status !== "merged" || readback.mergedSha !== headSha || readback.targetHead !== headSha) {
    throw new Error("already-completed run detected but MR readback is inconsistent: " + JSON.stringify(readback));
  }
  const changedOut = (await sh("git show --name-status --format= HEAD", "List commit changed paths")).trim();
  const stagedFiles = changedOut
    ? changedOut.split(/\r?\n/).filter(Boolean).map((l) => {
        const parts = l.split("\t");
        return { status: parts[0], path: parts.slice(1).join("\t") };
      })
    : [];
  if (Array.isArray(input.expectedChangedPaths)) {
    const actual = stagedFiles.map((f) => f.path).sort();
    const expected = input.expectedChangedPaths.map(String).sort();
    if (JSON.stringify(actual) !== JSON.stringify(expected)) {
      throw new Error("already-completed commit file set mismatch: got " + JSON.stringify(actual) + ", expected " + JSON.stringify(expected));
    }
  }
  const mainSha = (await sh("git rev-parse " + sq(baselineRef), "Resolve baseline ref at end")).trim();
  if (mainSha !== baselineSha) throw new Error("local baseline ref moved: " + mainSha + " != " + baselineSha);
  return {
    commitSha: headSha,
    baselineSha,
    mrId: String(mergedMr.id),
    mrStatus: readback.status,
    mergedSha: readback.mergedSha,
    targetHead: readback.targetHead,
    branch,
    mainSha,
    commitsAfterBaseline: headCount,
    stagedFiles,
    remotes,
    finalCleanTree: true,
    readbackVerified: true,
  };
}

if (state0.targetHead !== baselineSha) {
  const done = await tryAlreadyCompleted();
  if (done) return done;
  throw new Error("service targetHead (" + state0.targetHead + ") does not match baseline " + baselineSha + " and the repo/service state does not match an already-completed run with these inputs; restore the fixture or adjust baselineRef");
}

await sh("git add -A", "Stage all pending changes");
const stagedOut = (await sh("git diff --cached --name-status", "List staged file changes")).trim();
const stagedFiles = stagedOut
  ? stagedOut.split(/\r?\n/).filter(Boolean).map((l) => {
      const parts = l.split("\t");
      return { status: parts[0], path: parts.slice(1).join("\t") };
    })
  : [];
if (stagedFiles.length === 0) throw new Error("nothing to stage; no pending changes to commit");
if (Array.isArray(input.expectedChangedPaths)) {
  const actual = stagedFiles.map((f) => f.path).sort();
  const expected = input.expectedChangedPaths.map(String).sort();
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error("staged file set mismatch: got " + JSON.stringify(actual) + ", expected " + JSON.stringify(expected));
  }
}

await sh("git commit -m " + sq(input.commitMessage), "Create single local commit");
const commitSha = (await sh("git rev-parse HEAD", "Resolve new HEAD sha")).trim();
const parentSha = (await sh("git rev-parse HEAD^", "Resolve parent of new commit")).trim();
const subject = (await sh("git log -1 --format=%s", "Show commit subject")).trim();
if (subject !== input.commitMessage) throw new Error("commit subject mismatch: got '" + subject + "'");
const postCommitStatus = (await sh("git status --porcelain", "Verify clean tree after commit")).trim();
if (postCommitStatus) throw new Error("working tree not clean after commit: " + postCommitStatus);
const countOut = (await sh("git rev-list --count " + sq(baselineSha + "..HEAD"), "Count commits after baseline")).trim();
const commitsAfterBaseline = parseInt(countOut, 10);
if (commitsAfterBaseline !== 1) throw new Error("expected exactly 1 commit after baseline, got " + commitsAfterBaseline);
if (parentSha !== baselineSha) throw new Error("commit parent does not match baseline: " + parentSha + " != " + baselineSha);

const created = await httpJson("POST", base + "/api/mrs", {
  sourceSha: commitSha,
  targetBase: baselineSha,
  title: input.title,
  idempotencyKey: input.idempotencyKeyCreate,
});
if (!created || created.status !== "opened") throw new Error("MR create did not return opened: " + JSON.stringify(created));
if (created.sourceSha !== commitSha || created.targetBase !== baselineSha) throw new Error("MR create echoed unexpected SHAs: " + JSON.stringify(created));
const mrId = String(created.id);
if (!mrId) throw new Error("MR create returned no id");

const merged = await httpJson("POST", base + "/api/mrs/" + mrId + "/merge", {
  expectedHead: commitSha,
  expectedTargetHead: baselineSha,
  idempotencyKey: input.idempotencyKeyMerge,
});
if (!merged || merged.status !== "merged") throw new Error("MR merge did not return merged: " + JSON.stringify(merged));
if (merged.mergedSha !== commitSha) throw new Error("mergedSha does not equal sourceSha: " + merged.mergedSha);

const readback = await httpJson("GET", base + "/api/mrs/" + mrId);
if (!readback || readback.status !== "merged") throw new Error("readback status is not merged: " + JSON.stringify(readback));
if (readback.mergedSha !== commitSha || readback.targetHead !== commitSha) throw new Error("readback SHAs inconsistent: " + JSON.stringify(readback));
const state1 = await httpJson("GET", base + "/api/state");
if (state1.targetHead !== commitSha) throw new Error("service targetHead after merge is not the commit sha: " + state1.targetHead);

const finalStatus = (await sh("git status --porcelain", "Verify final clean tree")).trim();
const finalCleanTree = finalStatus.length === 0;
if (!finalCleanTree) throw new Error("working tree not clean at end: " + finalStatus);
const finalHead = (await sh("git rev-parse HEAD", "Resolve final HEAD sha")).trim();
if (finalHead !== commitSha) throw new Error("local HEAD moved after merge: " + finalHead);
const mainSha = (await sh("git rev-parse " + sq(baselineRef), "Resolve baseline ref at end")).trim();
if (mainSha !== baselineSha) throw new Error("local baseline ref moved: " + mainSha + " != " + baselineSha);

return {
  commitSha,
  baselineSha,
  mrId,
  mrStatus: readback.status,
  mergedSha: readback.mergedSha,
  targetHead: readback.targetHead,
  branch,
  mainSha,
  commitsAfterBaseline,
  stagedFiles,
  remotes,
  finalCleanTree,
  readbackVerified: true,
};
